WITH base AS (SELECT id, session_id, event_type, page, event_time, duration_sec, CASE WHEN duration_sec >= 404 THEN 'High' WHEN duration_sec >= 65 THEN 'Medium' ELSE 'Low' END AS duration_sec_band, DATE_FORMAT(event_time, 'yyyy-MM') AS event_time_label FROM web_events WHERE page IS NOT NULL AND event_type = 'search') SELECT id FROM base EXCEPT SELECT id FROM web_events WHERE session_id IN (9, 17, 30);
